ALTER TABLE "auth_attempts" DROP CONSTRAINT "auth_attempts_session_check";--> statement-breakpoint
ALTER TABLE "auth_attempts" ADD CONSTRAINT "auth_attempts_session_check" CHECK (("auth_attempts"."purpose"='signin' and (("auth_attempts"."stage" in ('authorize','exchanging','confirm') and "auth_attempts"."original_session_id" is null and "auth_attempts"."existing_provider" is null) or ("auth_attempts"."stage" in ('reauth_authorize','reauth_exchanging') and "auth_attempts"."original_session_id" is null and "auth_attempts"."existing_provider" is not null and "auth_attempts"."existing_provider"<>"auth_attempts"."target_provider") or ("auth_attempts"."stage"='link_ready' and "auth_attempts"."original_session_id" is not null and "auth_attempts"."existing_provider" is not null and "auth_attempts"."existing_provider"<>"auth_attempts"."target_provider"))) or ("auth_attempts"."purpose"='link' and "auth_attempts"."original_session_id" is not null and "auth_attempts"."existing_provider" is not null and "auth_attempts"."existing_provider"<>"auth_attempts"."target_provider") or ("auth_attempts"."purpose"='delete' and "auth_attempts"."original_session_id" is not null and "auth_attempts"."existing_provider" is not null));